<?php $page=max(1,min(100000,(int)($_GET['page']??1)));$total=(int)$a->db->value('SELECT COUNT(*) FROM cy_bounties');$rows=$a->db->all('SELECT b.*,c.title,u.display_name FROM cy_bounties b JOIN cy_contents c ON c.id=b.content_id JOIN cy_users u ON u.id=b.owner_id ORDER BY b.id DESC LIMIT 30 OFFSET ?',[($page-1)*30]);$held=(int)$a->db->value("SELECT COALESCE(SUM(amount),0) FROM cy_bounties WHERE status='open'"); ?>
<div class="admin-title"><div><span class="eyebrow">POINTS / ESCROW / ACCOUNTABILITY</span><h1><?= t('Question bounties') ?></h1><p><?= t('Awarded points are final. Only open escrow can be returned; every movement is recorded in the asset ledger.') ?></p></div><span class="pill soft"><?= t('Held points') ?>: <?= $held ?></span></div>
<section class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th><?= t('Question') ?></th><th><?= t('Owner') ?></th><th><?= t('Points') ?></th><th><?= t('Status') ?></th><th><?= t('Deadline') ?></th><th><?= t('Manage') ?></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><a href="<?= e(url('article',['id'=>$row['content_id']])) ?>"><?= e($row['title']) ?></a></td><td><?= e($row['display_name']) ?></td><td><?= (int)$row['amount'] ?></td><td><span class="pill"><?= t($row['status']) ?></span><?php if((int)$row['winner_id']): ?><small> UID <?= (int)$row['winner_id'] ?></small><?php endif ?></td><td><?= dt((int)$row['expires_at'],'Y.m.d H:i') ?></td><td><?php if($row['status']==='open'): ?><?= form_start('admin_bounty_release') . hidden('content_id',$row['content_id']) ?><?php button('Return escrow','secondary small','refresh'); ?></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php if(!$rows){empty_state('No bounties yet.','gift');}partial('pagination',['tab'=>'bounties','pagination'=>['page'=>$page,'pages'=>max(1,(int)ceil($total/30))]]); ?></section>
